package handlers
import (
 "io"
 "net/http"
 "os"
 "path/filepath"
 "mime"
 "strings"
 "log/slog"
 "fluxo/utils"
 "github.com/google/uuid"
 "github.com/gorilla/mux"
)
func(a *API)removeFile(name string){if filepath.Base(name)!=name{return};if err:=os.Remove(filepath.Join(a.UploadDir,name));err!=nil&&!os.IsNotExist(err){slog.Warn("remove attachment","error",err)}}
func(a *API)Attachments(w http.ResponseWriter,r *http.Request){id:=mux.Vars(r)["id"];if _,ok:=a.allowed(w,r,id);!ok{return};if r.Method=="POST"{r.Body=http.MaxBytesReader(w,r.Body,11<<20);if err:=r.ParseMultipartForm(1<<20);err!=nil{utils.Error(w,400,"O arquivo deve ter até 10 MB.");return};if r.MultipartForm!=nil{defer r.MultipartForm.RemoveAll()};file,header,err:=r.FormFile("arquivo");if err!=nil{utils.Error(w,400,"Envie um arquivo.");return};defer file.Close();if header.Size>10<<20{utils.Error(w,400,"O arquivo deve ter até 10 MB.");return};name:=filepath.Base(strings.ReplaceAll(header.Filename,"\\","/"));if len(name)>255||name=="."||name==""{utils.Error(w,400,"Nome de arquivo inválido.");return};if err=os.MkdirAll(a.UploadDir,0700);err!=nil{utils.Error(w,500,"Armazenamento indisponível.");return};key:=uuid.NewString();dest,err:=os.OpenFile(filepath.Join(a.UploadDir,key),os.O_CREATE|os.O_EXCL|os.O_WRONLY,0600);if err!=nil{utils.Error(w,500,"Não foi possível salvar o arquivo.");return};length,err:=io.Copy(dest,io.LimitReader(file,(10<<20)+1));closeErr:=dest.Close();if err!=nil||closeErr!=nil||length>10<<20{a.removeFile(key);utils.Error(w,400,"Não foi possível salvar o arquivo. Limite de 10 MB.");return};_,err=a.Repo.DB.Exec(r.Context(),"INSERT INTO anexos(tarefa_id,usuario_id,nome,mime,tamanho,arquivo) VALUES($1,$2,$3,$4,$5,$6)",id,User(r).ID,name,"application/octet-stream",length,key);if err!=nil{a.removeFile(key);utils.DBError(w,err);return}};rows,err:=a.Repo.DB.Query(r.Context(),"SELECT id::text,nome,tamanho,criado_em FROM anexos WHERE tarefa_id=$1 ORDER BY criado_em",id);if err!=nil{utils.DBError(w,err);return};defer rows.Close();result:=[]map[string]any{};for rows.Next(){var id,name string;var size int64;var created any;if err=rows.Scan(&id,&name,&size,&created);err!=nil{utils.DBError(w,err);return};result=append(result,map[string]any{"id":id,"nome":name,"tamanho":size,"criado_em":created})};if err=rows.Err();err!=nil{utils.DBError(w,err);return};utils.JSON(w,200,result)}
func(a *API)Attachment(w http.ResponseWriter,r *http.Request){id:=mux.Vars(r)["id"];var taskID,name,key string;err:=a.Repo.DB.QueryRow(r.Context(),"SELECT tarefa_id::text,nome,arquivo FROM anexos WHERE id=$1",id).Scan(&taskID,&name,&key);if err!=nil{utils.DBError(w,err);return};if _,ok:=a.allowed(w,r,taskID);!ok{return};if r.Method=="DELETE"{if !manager(w,r){return};if _,err=a.Repo.DB.Exec(r.Context(),"DELETE FROM anexos WHERE id=$1",id);err!=nil{utils.DBError(w,err);return};a.removeFile(key);utils.JSON(w,204,nil);return};if filepath.Base(key)!=key{utils.Error(w,500,"Arquivo indisponível.");return};f,err:=os.Open(filepath.Join(a.UploadDir,key));if err!=nil{utils.Error(w,404,"Arquivo não encontrado.");return};defer f.Close();info,err:=f.Stat();if err!=nil{utils.Error(w,500,"Arquivo indisponível.");return};w.Header().Set("Content-Type","application/octet-stream");w.Header().Set("Content-Disposition",mime.FormatMediaType("attachment",map[string]string{"filename":name}));w.Header().Set("X-Content-Type-Options","nosniff");w.Header().Set("Cache-Control","no-store");http.ServeContent(w,r,name,info.ModTime(),f)}
